use vstd::prelude::*;

verus! {

fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires
        // The two input arrays must have the same length
        a.len() == b.len(),
    ensures
        // The result has the same length as the inputs
        result.len() == a.len(),
        // For every valid index i, result[i] == (a[i] >= b[i])
        forall |i: usize| i < a.len() ==>
            result.get(i) == (a.get(i) >= b.get(i)),
{
    let n = a.len();
    let mut result: Vec<bool> = Vec::new();
    let mut idx: usize = 0;
    // We iterate from 0 up to n, building result one element at a time.
    while idx < n
        invariant
            idx <= n,
            // We've pushed exactly idx elements so far
            result.len() == idx,
            // And each of those satisfies the specification
            forall |j: usize| j < idx ==>
                result.get(j) == (a.get(j) >= b.get(j)),
        decreases n - idx,
    {
        let ai = a.get(idx);
        let bi = b.get(idx);
        // Compare and push the boolean into the result vector
        result.push(ai >= bi);
        idx += 1;
    }
    result
}

} // end of verus! block

fn main() {
    // Example usage; can be removed if not needed.
    let a = Vec::from(vec![1i8, -5, 127, 0]);
    let b = Vec::from(vec![0i8, -5,  42, 1]);
    let res = greater_equal(a.clone(), b.clone());
    assert!(res.len() == a.len());
    for i in 0..a.len() {
        assert!(res.get(i) == (a.get(i) >= b.get(i)));
    }
}

